using System.Globalization;
using System.Text;
using System.Text.Json.Nodes;

namespace Aw.Sindri.Features.Ship;

/// <summary>The PR body, generated by code from the packets (line spec §7.5, §11): the evidence pack as the body. It carries counts and verdicts of the hidden scenarios, never an id or text.</summary>
internal static class HandoffBody
{
    /// <summary>Renders the body.</summary>
    /// <param name="inputs">What the packets and the line say.</param>
    /// <returns>The Markdown.</returns>
    internal static string Render(HandoffInputs inputs)
    {
        var (sources, line, address, parents, _) = inputs;
        var body = new StringBuilder();
        _ = body.AppendLine(sources.Goal.Trim()).AppendLine();
        Acceptance(body, sources);
        Hidden(body, sources);
        _ = body.AppendLine("## Not proven").AppendLine().AppendLine(sources.NotProven.Trim()).AppendLine();
        _ = body.AppendLine("## Review").AppendLine().AppendLine(Text($"{Plural(sources.ReviewRounds, "round")} on `{sources.Head}`.")).AppendLine();
        _ = body.AppendLine("## Base").AppendLine().AppendLine(line.StackParent is null ? Text($"Opens against `{line.Base}`.") : Text($"Stacked on `{line.StackParent}`.")).AppendLine();
        _ = body.AppendLine("---").AppendLine(Text($"Generated by Sindri from frozen packets. Line `{address}`, head `{sources.Head}`."));
        foreach (var parent in parents)
        {
            _ = body.AppendLine(Text($"- `{parent}`"));
        }

        return body.ToString();
    }

    private static void Acceptance(StringBuilder body, PackSources sources)
    {
        _ = body.AppendLine("## Acceptance").AppendLine().AppendLine("| Item | Status | Evidence |").AppendLine("|---|---|---|");
        foreach (var item in sources.Items)
        {
            var evidence = (item["evidence"] as JsonArray ?? []).OfType<JsonObject>().Select(Reference);
            _ = body.AppendLine(Text($"| {Cell(ShipPacket.Text(item, "id"))}: {Cell(ShipPacket.Text(item, "text"))} | {Cell(ShipPacket.Text(item, "status"))} | {string.Join("<br>", evidence)} |"));
        }

        _ = body.AppendLine();
    }

    private static string Reference(JsonObject evidence) =>
        $"`{Cell(ShipPacket.Text(evidence, "path"))}` {Cell(ShipPacket.Text(evidence, "sha256"))} at {Cell(ShipPacket.Text(evidence, "commit"))}";

    private static void Hidden(StringBuilder body, PackSources sources)
    {
        var passing = sources.Hidden.Count(static v => string.Equals(v, "pass", StringComparison.Ordinal));
        _ = body.AppendLine("## Hidden scenarios").AppendLine().AppendLine(Text($"{passing} of {sources.Hidden.Count} passing on `{sources.Head}`.")).AppendLine();
    }

    private static string Text(FormattableString text) => text.ToString(CultureInfo.InvariantCulture);

    private static string Plural(int count, string noun) => string.Create(CultureInfo.InvariantCulture, $"{count} {noun}{(count == 1 ? string.Empty : "s")}");

    // A table cell is one line, and a pipe would end the cell.
    private static string Cell(string? text) => (text ?? string.Empty).Replace("|", "\\|", StringComparison.Ordinal).ReplaceLineEndings(" ");
}
